template <int kBlocksPerMatrix, int kN>
__global__ void reduce_packed_clustered(
    const float* __restrict__ input, float* __restrict__ matrix,
    float* __restrict__ column_reflectors,
    float* __restrict__ diagonal, float* __restrict__ off_diagonal,
    float* __restrict__ taus) {
